begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into auth.users(id,email) values ('85000000-0000-4000-8000-000000000001','voucher-admin@example.invalid'),('85000000-0000-4000-8000-000000000002','voucher-customer@example.invalid'),('85000000-0000-4000-8000-000000000003','voucher-other@example.invalid');
insert into public.profiles(id,full_name,role) values ('85000000-0000-4000-8000-000000000001','Voucher admin','admin'),('85000000-0000-4000-8000-000000000002','Voucher customer','player'),('85000000-0000-4000-8000-000000000003','Other customer','player') on conflict(id) do update set role=excluded.role;
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) values ('85000000-0000-4000-8000-000000000004','85000000-0000-4000-8000-000000000001','totp','verified','LOCAL-TEST-ONLY',now(),now());
insert into public.staff_orders(id,order_number,customer_id,booking_date,booking_time,players_count,total,subtotal,arena_id,payment_status,order_status,payment_method) values
 ('85000000-0000-4000-8000-000000000011','VOUCHER-SOURCE','85000000-0000-4000-8000-000000000002',current_date,'10:00',1,100000,100000,'arena-1','paid','completed','cash'),
 ('85000000-0000-4000-8000-000000000012','VOUCHER-TARGET',null,current_date,'10:00',1,100000,100000,'arena-1','unpaid','confirmed','unpaid'),
 ('85000000-0000-4000-8000-000000000013','VOUCHER-HISTORICAL',null,current_date,'10:00',1,50000,50000,'arena-1','paid','completed','bank_transfer');
insert into public.staff_order_payments(id,order_id,payment_method,amount) values('85000000-0000-4000-8000-000000000021','85000000-0000-4000-8000-000000000011','cash',100000);
select ok(not has_function_privilege('anon','public.staff_convert_payment_to_voucher(uuid,uuid,uuid,integer,text)','execute'),'Anonymous cannot issue credit');
select ok(not has_table_privilege('authenticated','public.payment_vouchers','insert'),'Direct issuance forbidden');
select ok(not has_table_privilege('authenticated','public.payment_vouchers','update'),'Direct balance edits forbidden');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"85000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select throws_ok($q$select public.staff_convert_payment_to_voucher('85000000-0000-4000-8000-000000000011','85000000-0000-4000-8000-000000000021','85000000-0000-4000-8000-000000000031',40000,'Change of plans')$q$,'P0001','Staff access required.','MFA required');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"85000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
select lives_ok($q$select public.staff_convert_payment_to_voucher('85000000-0000-4000-8000-000000000011','85000000-0000-4000-8000-000000000021','85000000-0000-4000-8000-000000000031',40000,'Change of plans')$q$,'Completed payment converts partially');
select is((select balance from public.payment_vouchers where id='85000000-0000-4000-8000-000000000031'),40000,'Credit immediately available');
select matches((select code from public.payment_vouchers where id='85000000-0000-4000-8000-000000000031'),'^[A-HJ-NP-Z2-9]{8}$','Code is eight unambiguous characters');
select is((select customer_id::text from public.payment_vouchers where id='85000000-0000-4000-8000-000000000031'),'85000000-0000-4000-8000-000000000002','Customer is linked automatically');
select throws_ok($q$update public.staff_orders set payment_status='refunded' where order_number='VOUCHER-SOURCE'$q$,'P0001','This order has voucher credit. Reconcile its voucher ledger before a cash refund.','Cannot refund money twice');
select is((select total from public.staff_orders where order_number='VOUCHER-SOURCE'),60000,'Order value reduced by credit');
select is((select sum(amount)::integer from public.staff_order_payments where order_id='85000000-0000-4000-8000-000000000011'),60000,'Net ledger matches source value');
select is((select amount from public.staff_order_payments where id='85000000-0000-4000-8000-000000000021'),100000,'Original cash receipt retained');
select lives_ok($q$select public.staff_convert_payment_to_voucher('85000000-0000-4000-8000-000000000011','85000000-0000-4000-8000-000000000021','85000000-0000-4000-8000-000000000031',40000,'Change of plans')$q$,'Lost response retry is idempotent');
select throws_ok($q$select public.staff_convert_payment_to_voucher('85000000-0000-4000-8000-000000000011','85000000-0000-4000-8000-000000000021','85000000-0000-4000-8000-000000000031',50000,'Change of plans')$q$,'P0001','Request reference already used.','Changed retry rejected');
select throws_ok($q$select public.staff_convert_payment_to_voucher('85000000-0000-4000-8000-000000000011','85000000-0000-4000-8000-000000000021','85000000-0000-4000-8000-000000000032',70000,'Too much credit')$q$,'P0001','Amount exceeds the unconverted payment or order value.','Cannot overconvert');
select throws_ok($q$update public.staff_order_payments set amount=1 where id='85000000-0000-4000-8000-000000000021'$q$,'P0001','Voucher-linked receipts are immutable.','Cannot mutate backing receipt');
select throws_ok($q$insert into public.staff_order_payments(order_id,payment_method,amount) values('85000000-0000-4000-8000-000000000012','voucher',10000)$q$,'P0001','Use the voucher redemption action.','Cannot fabricate voucher payment');
select lives_ok($q$select public.staff_redeem_payment_voucher('85000000-0000-4000-8000-000000000012',(select code from public.payment_vouchers where id='85000000-0000-4000-8000-000000000031'),'85000000-0000-4000-8000-000000000041',15000)$q$,'Partial redemption succeeds');
select lives_ok($q$select public.staff_redeem_payment_voucher('85000000-0000-4000-8000-000000000012',(select code from public.payment_vouchers where id='85000000-0000-4000-8000-000000000031'),'85000000-0000-4000-8000-000000000041',15000)$q$,'Redemption retry succeeds once');
select is((select balance from public.payment_vouchers where id='85000000-0000-4000-8000-000000000031'),25000,'Retry does not double spend');
select throws_ok($q$select public.staff_redeem_payment_voucher('85000000-0000-4000-8000-000000000012',(select code from public.payment_vouchers where id='85000000-0000-4000-8000-000000000031'),'85000000-0000-4000-8000-000000000042',26000)$q$,'P0001','Amount exceeds voucher balance or order balance.','Cannot overdraw');
select lives_ok($q$select public.staff_convert_payment_to_voucher('85000000-0000-4000-8000-000000000013',null,'85000000-0000-4000-8000-000000000033',50000,'Full historical conversion')$q$,'Historical completed payment converts fully');
select is((select total from public.staff_orders where order_number='VOUCHER-HISTORICAL'),0,'Full conversion zeros net value');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"85000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
select is((select count(*)::integer from public.payment_vouchers),1,'Customer can read their voucher');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"85000000-0000-4000-8000-000000000003","aal":"aal1"}',true);
select is((select count(*)::integer from public.payment_vouchers),0,'Other customer cannot list codes');
reset role;
-- Public lookup requires no profile, never reveals the original customer's identity.
select set_config('test.voucher_code',(select code from public.payment_vouchers where id='85000000-0000-4000-8000-000000000031'),true);
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select lives_ok($q$select public.payment_voucher_quote(current_setting('test.voucher_code'),'ha-do-centrosa')$q$,'Guest can check a code without private-schema access');
select is((public.payment_voucher_quote(current_setting('test.voucher_code'),'ha-do-centrosa')->>'balance')::integer,25000,'Guest quote returns current balance');
select ok(public.payment_voucher_quote(current_setting('test.voucher_code'),'cafe-des-stagiaires') ? 'error','Wrong venue is rejected');
select throws_ok($q$select public.book_ticket_with_payment_voucher('create_sim_racing_booking',jsonb_build_object('p_date',current_date+30,'p_start_time','03:00','p_guest_phone','+84987654099','p_guest_name','Voucher test'),current_setting('test.voucher_code'),'85000000-0000-4000-8000-000000000051')$q$,'P0001',null,'Invalid booking does not spend credit');
select is((public.payment_voucher_quote(current_setting('test.voucher_code'),'ha-do-centrosa')->>'balance')::integer,25000,'Failed booking leaves voucher intact');
select lives_ok($q$select public.book_ticket_with_payment_voucher('create_sim_racing_booking',jsonb_build_object('p_date',current_date+30,'p_start_time','09:00','p_guest_phone','+84987654099','p_guest_name','Voucher test'),current_setting('test.voucher_code'),'85000000-0000-4000-8000-000000000051')$q$,'Guest booking consumes stored credit atomically');
select lives_ok($q$select public.book_ticket_with_payment_voucher('create_sim_racing_booking',jsonb_build_object('p_date',current_date+30,'p_start_time','09:00','p_guest_phone','+84987654099','p_guest_name','Voucher test'),current_setting('test.voucher_code'),'85000000-0000-4000-8000-000000000051')$q$,'Online lost response retries return the saved booking');
reset role;
select is((select balance from public.payment_vouchers where id='85000000-0000-4000-8000-000000000031'),0,'Online use deducts exact available credit');
select is((select count(*)::integer from public.payment_voucher_redemptions where id='85000000-0000-4000-8000-000000000051'),1,'Online retry creates one redemption');
select is((select response->>'amount_due' from private.payment_voucher_booking_requests where id='85000000-0000-4000-8000-000000000051'),'125000','Remaining cash due is separate from voucher payment');

-- Exercise both VR booking engines as well as simulator redemption above.
select set_config('request.jwt.claims','{"role":"authenticated","sub":"85000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
select public.staff_convert_payment_to_voucher('85000000-0000-4000-8000-000000000011','85000000-0000-4000-8000-000000000021','85000000-0000-4000-8000-000000000061',30000,'VR guest voucher');
select set_config('test.vr_price',public.ticket_tariff_unit_price('ha-do-centrosa','individual',current_date+45,'10:00')::text,true);
select set_config('test.vr_code',(select code from public.payment_vouchers where id='85000000-0000-4000-8000-000000000061'),true);
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select lives_ok($q$select public.book_ticket_with_payment_voucher('create_guest_ticket_booking',jsonb_build_object('p_ticket_type','individual','p_date',current_date+45,'p_start_time','10:00','p_duration_minutes',30,'p_player_count',1,'p_arena_count',1,'p_game_options',jsonb_build_array('city-z'),'p_unit_price',current_setting('test.vr_price')::integer,'p_total_price',current_setting('test.vr_price')::integer,'p_guest_phone','0987654097','p_guest_name','VR guest'),current_setting('test.vr_code'),'85000000-0000-4000-8000-000000000062')$q$,'Ha Do guest VR checkout accepts short voucher');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into public.staff_orders(id,order_number,booking_date,booking_time,players_count,total,subtotal,arena_id,payment_status,order_status,payment_method) values('85000000-0000-4000-8000-000000000071','VOUCHER-CAFE',current_date,'10:00',1,200000,200000,'cafe:arena-1','paid','completed','cash');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"85000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
select public.staff_convert_payment_to_voucher('85000000-0000-4000-8000-000000000071',null,'85000000-0000-4000-8000-000000000072',200000,'Cafe guest voucher');
select set_config('test.cafe_code',(select code from public.payment_vouchers where id='85000000-0000-4000-8000-000000000072'),true);
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select lives_ok($q$select public.book_ticket_with_payment_voucher('create_cafe_ticket_booking_request',jsonb_build_object('p_ticket_type','individual','p_date',current_date+46,'p_start_time','16:00','p_duration_minutes',30,'p_player_count',1,'p_arena_count',1,'p_game_options',jsonb_build_array('city-z'),'p_guest_phone','0987654096','p_guest_name','Cafe guest'),current_setting('test.cafe_code'),'85000000-0000-4000-8000-000000000073')$q$,'Thao Dien guest VR checkout accepts short voucher');
reset role;

select set_config('request.jwt.claims','{"role":"service_role"}',true);
update public.profiles set phone='+84987654095',birthday='1990-01-01' where id='85000000-0000-4000-8000-000000000002';
select set_config('request.jwt.claims','{"role":"authenticated","sub":"85000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
select public.staff_convert_payment_to_voucher('85000000-0000-4000-8000-000000000011','85000000-0000-4000-8000-000000000021','85000000-0000-4000-8000-000000000081',30000,'Account VR voucher');
select set_config('test.account_code',(select code from public.payment_vouchers where id='85000000-0000-4000-8000-000000000081'),true);
select set_config('test.account_price',public.ticket_tariff_unit_price('ha-do-centrosa','individual',current_date+48,'10:00')::text,true);
select set_config('request.jwt.claims','{"role":"authenticated","sub":"85000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
set local role authenticated;
select lives_ok($q$select public.book_ticket_with_payment_voucher('create_ticket_booking',jsonb_build_object('p_ticket_type','individual','p_date',current_date+48,'p_start_time','10:00','p_duration_minutes',30,'p_player_count',1,'p_arena_count',1,'p_game_options',jsonb_build_array('city-z'),'p_unit_price',current_setting('test.account_price')::integer,'p_total_price',current_setting('test.account_price')::integer),current_setting('test.account_code'),'85000000-0000-4000-8000-000000000082')$q$,'Signed-in customer VR checkout accepts voucher and creates a paid ledger');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into public.staff_orders(id,order_number,booking_date,booking_time,players_count,total,subtotal,arena_id,payment_status,order_status,payment_method) values('85000000-0000-4000-8000-000000000091','VOUCHER-PARTIAL',current_date,'10:00',1,100000,100000,'arena-1','partially_paid','partially_paid','cash');
insert into public.staff_order_payments(id,order_id,payment_method,amount) values('85000000-0000-4000-8000-000000000092','85000000-0000-4000-8000-000000000091','cash',40000);
select set_config('request.jwt.claims','{"role":"authenticated","sub":"85000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
set local role authenticated;
select lives_ok($q$select public.staff_convert_payment_to_voucher('85000000-0000-4000-8000-000000000091','85000000-0000-4000-8000-000000000092','85000000-0000-4000-8000-000000000093',40000,'Convert entire partial receipt')$q$,'Full conversion of partial payment succeeds');
select is((select payment_status||'/'||order_status from public.staff_orders where id='85000000-0000-4000-8000-000000000091'),'unpaid/confirmed','Zero remaining paid amount restores collectible unpaid status');
select lives_ok($q$select public.staff_record_order_payment('85000000-0000-4000-8000-000000000091','85000000-0000-4000-8000-000000000094','cash',10000)$q$,'Remaining bill can still collect a payment');
select is((select total-(select sum(amount)::integer from public.staff_order_payments where order_id=o.id) from public.staff_orders o where id='85000000-0000-4000-8000-000000000091'),50000,'Unpaid balance reconciles after conversion and new receipt');
reset role;
select * from finish();
rollback;
